1	// SignalScout core types. Plain TypeScript only: no Next.js imports.
2	// Data flows through four layers: Raw -> Validation -> Assessment -> Run.
3	
4	// ---------------------------------------------------------------------------
5	// Layer 1: RawCompany (what Crustdata returned, never edited)
6	// ---------------------------------------------------------------------------
7	
8	// Which Crustdata endpoint produced the data: "search" is the cheap list
9	// lookup, "enrich" is the paid, detailed lookup for one company.
10	export type SourceEndpoint = "search" | "enrich";
11	
12	// Fields every search result carries. Any text field may be an empty string
13	// when Crustdata has no value for it.
14	export interface RawSearchFields {
15	  // Crustdata's own numeric ID for the company. Our unique key.
16	  readonly crustdata_company_id: number;
17	  // Company name as Crustdata reports it.
18	  readonly name: string;
19	  // Main web domain, e.g. "acme.com". Different companies can share one.
20	  readonly primary_domain: string;
21	  // Company website URL as listed.
22	  readonly website: string;
23	  // The company's LinkedIn page URL.
24	  readonly professional_network_url: string;
25	  // Headcount bucket as text, e.g. "51-200".
26	  readonly employee_count_range: string;
27	  // Industry label as Crustdata reports it.
28	  readonly industry: string;
29	  // URL of the company logo image.
30	  readonly logo: string;
31	}
32	
33	// City / state / country of the company. Each part may be missing.
34	export interface RawLocation {
35	  // City name.
36	  readonly city?: string;
37	  // State or region.
38	  readonly state?: string;
39	  // Country name.
40	  readonly country?: string;
41	}
42	
43	// Extra fields only the enrich endpoint returns. All are optional because
44	// enrichment can come back partial.
45	export interface RawEnrichmentFields {
46	  // Free-text company description.
47	  readonly description?: string;
48	  // Year the company was founded.
49	  readonly founded_year?: number;
50	  // Legal structure, e.g. "Privately Held".
51	  readonly legal_type?: string;
52	  // Most recent total employee count.
53	  readonly latest_headcount?: number;
54	  // Revenue bucket as text, e.g. "$10M-$50M".
55	  readonly revenue_range?: string;
56	  // Where the company is based.
57	  readonly location?: RawLocation;
58	  // Topics / skills the company lists about itself.
59	  readonly specialities?: readonly string[];
60	  // Number of LinkedIn followers.
61	  readonly linkedin_followers?: number;
62	}
63	
64	// A company exactly as Crustdata gave it, plus bookkeeping about the call.
65	// Enrichment fields are absent for companies that were only searched.
66	export interface RawCompany extends RawSearchFields, RawEnrichmentFields {
67	  // Which endpoint this data came from.
68	  readonly source: SourceEndpoint;
69	  // When we received it, as an ISO 8601 timestamp.
70	  readonly retrieved_at: string;
71	  // What this one call cost in US dollars.
72	  readonly cost_usd: number;
73	}
74	
75	// ---------------------------------------------------------------------------
76	// Layer 2: Validation (decided by code rules, never by the model)
77	// ---------------------------------------------------------------------------
78	
79	// Overall verdict: "valid" = good to use, "flagged" = usable but suspicious,
80	// "rejected" = dropped from results.
81	export type ValidationStatus = "valid" | "flagged" | "rejected";
82	
83	// Machine-readable name of each rule that can fail.
84	export type ValidationIssueCode =
85	  | "missing_name" // no company name
86	  | "missing_domain" // no primary domain
87	  | "junk_website" // website is a placeholder or not a real site
88	  | "duplicate_domain" // another company in this run has the same domain (or LinkedIn URL)
89	  | "size_headcount_mismatch" // size bucket and headcount disagree
90	  | "missing_linkedin"; // no LinkedIn page
91	
92	// One problem found by a validation rule.
93	export interface ValidationIssue {
94	  // Which rule failed.
95	  readonly code: ValidationIssueCode;
96	  // The raw field the rule looked at, e.g. "primary_domain".
97	  readonly field: string;
98	  // Plain-English explanation of the problem.
99	  readonly reason: string;
100	  // For duplicate issues: the crustdata_company_id of the other record this
101	  // one appears to duplicate. Unused for other issue codes.
102	  readonly related_company_id?: number;
103	}
104	
105	// Result of running all code rules on one company.
106	export interface Validation {
107	  // The overall verdict.
108	  readonly status: ValidationStatus;
109	  // Every problem found. Empty when the company is clean.
110	  readonly issues: readonly ValidationIssue[];
111	}
112	
113	// ---------------------------------------------------------------------------
114	// Layer 3: Assessment (model-written judgement, grounded in evidence)
115	// ---------------------------------------------------------------------------
116	
117	// How much we trust a piece of evidence:
118	// "given" = the user stated it in their request,
119	// "extracted" = read from one raw field,
120	// "cross_checked" = confirmed by two or more sources,
121	// "uncertain" = a guess or weakly supported.
122	export type EvidenceStatus =
123	  | "given"
124	  | "extracted"
125	  | "cross_checked"
126	  | "uncertain";
127	
128	// One factual claim the assessment relies on.
129	export interface Evidence {
130	  // Short unique ID within the assessment, e.g. "e1".
131	  readonly id: string;
132	  // The claim in plain English, e.g. "Has about 120 employees".
133	  readonly claim: string;
134	  // The raw fields this claim rests on, e.g. ["latest_headcount"].
135	  // "cross_checked" evidence needs at least two fields; "given" or
136	  // "extracted" evidence needs at least one.
137	  readonly source_fields: readonly (keyof RawCompany)[];
138	  // How trustworthy the claim is.
139	  readonly status: EvidenceStatus;
140	}
141	
142	// A score for one criterion from the user's request (e.g. "right size").
143	export interface CriterionScore {
144	  // Name of the criterion.
145	  readonly criterion: string;
146	  // Score from 0 (no match) to 100 (perfect match).
147	  readonly score: number;
148	  // Evidence IDs backing this score.
149	  readonly evidence_ids: readonly string[];
150	}
151	
152	// A draft first message to the company.
153	// Rule: it may only cite evidence whose status is "given" or "cross_checked".
154	export interface OutreachDraft {
155	  // The message text.
156	  readonly body: string;
157	  // IDs of the evidence items the message relies on.
158	  readonly cited_evidence_ids: readonly string[];
159	}
160	
161	// The model's overall view of how well a company fits the request.
162	export interface Assessment {
163	  // Overall fit from 0 (poor) to 100 (excellent).
164	  readonly fit_score: number;
165	  // Score for each criterion.
166	  readonly criterion_scores: readonly CriterionScore[];
167	  // All facts used, each with a trust level.
168	  readonly evidence: readonly Evidence[];
169	  // Things the model could not confirm or is unsure about.
170	  readonly uncertainty_notes: readonly string[];
171	  // Optional first-contact message. Absent if no safe evidence to cite.
172	  readonly outreach?: OutreachDraft;
173	}
174	
175	// ---------------------------------------------------------------------------
176	// Prospect: the three company layers together
177	// ---------------------------------------------------------------------------
178	
179	// One company moving through the pipeline. Assessment is added only after
180	// the company passes validation and gets enriched.
181	// Identity is raw.crustdata_company_id. Duplicate DETECTION is separate: it
182	// compares the normalised domain (lowercase, no protocol, no www, no trailing
183	// slash), falling back to the normalised LinkedIn URL when the domain is
184	// empty. A match raises a duplicate_domain issue (with related_company_id)
185	// and the earlier or cheaper record is kept. Two different Crustdata ids
186	// sharing a domain are a probable duplicate, not proof of identity.
187	export interface Prospect {
188	  // Untouched Crustdata data.
189	  readonly raw: RawCompany;
190	  // Code-rule verdict.
191	  readonly validation: Validation;
192	  // Model judgement, if one was made.
193	  readonly assessment?: Assessment;
194	}
195	
196	// ---------------------------------------------------------------------------
197	// Layer 4: Run (one end-to-end execution of the agent)
198	// ---------------------------------------------------------------------------
199	
200	// Hard limits that keep a run from costing too much.
201	export interface RunConfig {
202	  // Most companies to pull from search. Default 100.
203	  readonly max_search_results: number;
204	  // Most companies to send to paid enrichment. Default 15.
205	  readonly max_enrichments: number;
206	}
207	
208	// Default limits used when the caller sets none.
209	export const DEFAULT_RUN_CONFIG: RunConfig = {
210	  max_search_results: 100,
211	  max_enrichments: 15,
212	};
213	
214	// How many companies reached each stage.
215	export interface RunCounts {
216	  // Companies returned by search.
217	  readonly searched: number;
218	  // Companies that were enriched.
219	  readonly enriched: number;
220	  // Companies in the final results.
221	  readonly delivered: number;
222	}
223	
224	// Pipeline step names, used for cost and timing breakdowns.
225	export type RunStep = "search" | "validate" | "enrich" | "assess";
226	
227	// Dollars spent in each step.
228	export type RunCosts = Readonly<Record<RunStep, number>>;
229	
230	// Milliseconds spent in each step.
231	export type RunTimings = Readonly<Record<RunStep, number>>;
232	
233	// Record of one agent run.
234	export interface Run {
235	  // Unique ID that ties logs and traces to this run.
236	  readonly trace_id: string;
237	  // The user's plain-language description of who they want to find.
238	  readonly input_description: string;
239	  // Limits this run used.
240	  readonly config: RunConfig;
241	  // Stage-by-stage company counts.
242	  readonly counts: RunCounts;
243	  // US dollars spent per step.
244	  readonly cost_usd_by_step: RunCosts;
245	  // Milliseconds spent per step.
246	  readonly timings_ms_by_step: RunTimings;
247	}
