// Normalisers used for duplicate detection and junk-host checks.
// Pure string helpers: no network, no throwing.

const PROTOCOL = /^[a-z][a-z0-9+.-]*:\/\//;

// Lowercased host only: no protocol, "www.", port, path, query, hash,
// trailing slash or trailing dot. Returns "" when nothing is left.
export function normalizeDomain(input: string): string {
  let s = String(input ?? "").trim().toLowerCase();
  s = s.replace(PROTOCOL, "");
  s = s.split(/[/?#]/)[0] ?? "";
  s = s.replace(/^[^@]*@/, ""); // user:pass@host
  s = s.replace(/:\d+$/, ""); // port
  s = s.replace(/^www\./, "");
  s = s.replace(/\.+$/, "");
  return s;
}

// Lowercased LinkedIn URL without protocol, "www.", query, hash or trailing
// slash. Returns "" when nothing is left.
export function normalizeLinkedInUrl(input: string): string {
  let s = String(input ?? "").trim().toLowerCase();
  s = s.replace(PROTOCOL, "");
  s = s.replace(/^www\./, "");
  s = s.split(/[?#]/)[0] ?? "";
  s = s.replace(/\/+$/, "");
  return s;
}

// Code-rule validation of raw companies. Pure and deterministic: the same
// input always gives the same output, and no rule ever throws.

import type {
  RawCompany,
  Validation,
  ValidationIssue,
  ValidationStatus,
} from "../types";
import { normalizeDomain, normalizeLinkedInUrl } from "./normalize";

// Hosts that are messaging, link-shortener or social pages, not real sites.
export const JUNK_HOSTS: readonly string[] = [
  "wa.link",
  "wa.me",
  "bit.ly",
  "linktr.ee",
  "facebook.com",
  "instagram.com",
  "t.me",
];

// Above this implied revenue per employee (USD) the data is not believable.
export const MAX_REVENUE_PER_EMPLOYEE_USD = 500000;

interface Range {
  readonly min: number;
  readonly max: number; // Infinity for open-ended ranges like "10,001+"
}

function toNumber(text: string): number | undefined {
  const n = Number(text.replace(/,/g, ""));
  return Number.isFinite(n) ? n : undefined;
}

// "51-200" -> {51, 200}; "10,001+" -> {10001, Infinity}; else undefined.
export function parseEmployeeRange(input: unknown): Range | undefined {
  if (typeof input !== "string") return undefined;
  const s = input.trim();
  const span = /^(\d[\d,]*)\s*[-–]\s*(\d[\d,]*)$/.exec(s);
  if (span) {
    const min = toNumber(span[1]);
    const max = toNumber(span[2]);
    if (min === undefined || max === undefined || max < min) return undefined;
    return { min, max };
  }
  const open = /^(\d[\d,]*)\s*\+$/.exec(s);
  if (open) {
    const min = toNumber(open[1]);
    return min === undefined ? undefined : { min, max: Infinity };
  }
  return undefined;
}

const SUFFIX: Readonly<Record<string, number>> = {
  "": 1,
  k: 1e3,
  m: 1e6,
  b: 1e9,
};

// Lower bound in USD of a range like "$10M-$50M", "$500K-$1M" or "$10M+".
// Undefined for anything else (e.g. "<$1M", "unknown").
export function parseRevenueLowerBound(input: unknown): number | undefined {
  if (typeof input !== "string") return undefined;
  const m = /^\$?\s*(\d[\d,]*(?:\.\d+)?)\s*([kmb]?)\s*(?:[-–]|to\b|\+|$)/i.exec(
    input.trim(),
  );
  if (!m) return undefined;
  const base = toNumber(m[1]);
  if (base === undefined) return undefined;
  return base * (SUFFIX[m[2].toLowerCase()] ?? 1);
}

function isEmpty(value: unknown): boolean {
  return typeof value !== "string" || value.trim() === "";
}

function isJunkHost(host: string): boolean {
  return JUNK_HOSTS.some((j) => host === j || host.endsWith(`.${j}`));
}

// Key used to group duplicates: domain first, LinkedIn URL when no domain.
function duplicateKey(raw: RawCompany): string | undefined {
  const domain = normalizeDomain(raw.primary_domain);
  if (domain) return `domain:${domain}`;
  const linkedin = normalizeLinkedInUrl(raw.professional_network_url);
  if (linkedin) return `linkedin:${linkedin}`;
  return undefined;
}

function sizeIssues(raw: RawCompany): ValidationIssue[] {
  const issues: ValidationIssue[] = [];
  const headcount = raw.latest_headcount;
  if (
    typeof headcount !== "number" ||
    !Number.isFinite(headcount) ||
    headcount <= 0
  ) {
    return issues;
  }

  const range = parseEmployeeRange(raw.employee_count_range);
  if (range && (headcount < range.min || headcount > range.max)) {
    issues.push({
      code: "size_headcount_mismatch",
      field: "latest_headcount",
      reason: `Headcount ${headcount} is outside the listed size range "${raw.employee_count_range}".`,
    });
  }

  const revenueMin = parseRevenueLowerBound(raw.revenue_range);
  if (
    revenueMin !== undefined &&
    revenueMin / headcount > MAX_REVENUE_PER_EMPLOYEE_USD
  ) {
    issues.push({
      code: "size_headcount_mismatch",
      field: "revenue_range",
      reason: `Revenue "${raw.revenue_range}" with ${headcount} employees implies more than $${MAX_REVENUE_PER_EMPLOYEE_USD.toLocaleString("en-US")} per employee, which is implausible.`,
    });
  }
  return issues;
}

export function validateCompanies(
  raws: readonly RawCompany[],
): readonly Validation[] {
  const firstSeen = new Map<string, number>(); // key -> crustdata_company_id

  return raws.map((raw): Validation => {
    const issues: ValidationIssue[] = [];

    const noName = isEmpty(raw.name);
    const domain = normalizeDomain(raw.primary_domain ?? "");
    const linkedin = normalizeLinkedInUrl(raw.professional_network_url ?? "");

    if (noName) {
      issues.push({
        code: "missing_name",
        field: "name",
        reason: "The company has no name.",
      });
    }
    if (!domain) {
      issues.push({
        code: "missing_domain",
        field: "primary_domain",
        reason: "The company has no primary domain.",
      });
    }

    const host = normalizeDomain(raw.website ?? "");
    if (host && isJunkHost(host)) {
      issues.push({
        code: "junk_website",
        field: "website",
        reason: `The website points to ${host}, a messaging, link-shortener or social page rather than a company site.`,
      });
    }

    if (!linkedin) {
      issues.push({
        code: "missing_linkedin",
        field: "professional_network_url",
        reason: "The company has no LinkedIn page.",
      });
    }

    let isLaterDuplicate = false;
    const key = duplicateKey(raw);
    if (key !== undefined) {
      const keptId = firstSeen.get(key);
      if (keptId === undefined) {
        firstSeen.set(key, raw.crustdata_company_id);
      } else {
        isLaterDuplicate = true;
        const viaDomain = key.startsWith("domain:");
        issues.push({
          code: "duplicate_domain",
          field: viaDomain ? "primary_domain" : "professional_network_url",
          reason: viaDomain
            ? `Another company (id ${keptId}) already uses the domain ${domain}.`
            : `Another company (id ${keptId}) already uses the LinkedIn page ${linkedin}.`,
          related_company_id: keptId,
        });
      }
    }

    issues.push(...sizeIssues(raw));

    let status: ValidationStatus;
    if ((noName && !domain && !linkedin) || isLaterDuplicate) {
      status = "rejected";
    } else if (issues.length > 0) {
      status = "flagged";
    } else {
      status = "valid";
    }
    return { status, issues };
  });
}

import { describe, expect, it } from "vitest";
import { FIXTURE_COMPANIES } from "../src/core/fixtures/companies";
import { normalizeDomain, normalizeLinkedInUrl } from "../src/core/data/normalize";
import {
  JUNK_HOSTS,
  MAX_REVENUE_PER_EMPLOYEE_USD,
  validateCompanies,
} from "../src/core/data/validation";
import type { RawCompany, ValidationIssueCode } from "../src/core/types";

const clean = FIXTURE_COMPANIES[0];

function make(overrides: Partial<RawCompany>): RawCompany {
  return { ...clean, ...overrides };
}

function codes(raw: RawCompany): ValidationIssueCode[] {
  return validateCompanies([raw])[0].issues.map((i) => i.code);
}

describe("normalize", () => {
  it("normalises domains", () => {
    expect(normalizeDomain("HTTPS://www.Acme.com/path?q=1")).toBe("acme.com");
    expect(normalizeDomain("acme.com./")).toBe("acme.com");
    expect(normalizeDomain("   ")).toBe("");
  });
  it("normalises LinkedIn URLs", () => {
    expect(
      normalizeLinkedInUrl("https://www.LinkedIn.com/company/Acme/?trk=x"),
    ).toBe("linkedin.com/company/acme");
  });
});

describe("rules", () => {
  it("passes a clean record", () => {
    expect(validateCompanies([clean])[0]).toEqual({ status: "valid", issues: [] });
  });

  it("missing_name", () => {
    expect(codes(make({ name: "   " }))).toEqual(["missing_name"]);
  });

  it("missing_domain", () => {
    expect(codes(make({ primary_domain: "" }))).toEqual(["missing_domain"]);
  });

  it("junk_website for every junk host", () => {
    for (const host of JUNK_HOSTS) {
      expect(codes(make({ website: `https://www.${host}/x` }))).toEqual([
        "junk_website",
      ]);
    }
    expect(codes(make({ website: "https://notbit.ly.example" }))).toEqual([]);
  });

  it("missing_linkedin", () => {
    expect(codes(make({ professional_network_url: "" }))).toEqual([
      "missing_linkedin",
    ]);
  });

  it("duplicate_domain keeps the first and points later ones at it", () => {
    const a = make({ crustdata_company_id: 1 });
    const b = make({
      crustdata_company_id: 2,
      primary_domain: "WWW.BrightwaterLabs.example/",
    });
    const [va, vb] = validateCompanies([a, b]);
    expect(va.issues).toEqual([]);
    expect(vb.issues).toHaveLength(1);
    expect(vb.issues[0]).toMatchObject({
      code: "duplicate_domain",
      related_company_id: 1,
    });
  });

  it("duplicate_domain falls back to LinkedIn URL when there is no domain", () => {
    const a = make({ crustdata_company_id: 1, primary_domain: "" });
    const b = make({
      crustdata_company_id: 2,
      primary_domain: "",
      professional_network_url: clean.professional_network_url.toUpperCase() + "/",
    });
    const [, vb] = validateCompanies([a, b]);
    expect(vb.issues.map((i) => i.code)).toContain("duplicate_domain");
    expect(vb.issues.find((i) => i.code === "duplicate_domain")).toMatchObject({
      related_company_id: 1,
    });
  });

  it("size_headcount_mismatch for headcount outside range", () => {
    expect(
      codes(make({ employee_count_range: "11-50", latest_headcount: 640 })),
    ).toEqual(["size_headcount_mismatch"]);
    expect(
      codes(make({ employee_count_range: "11-50", latest_headcount: 30 })),
    ).toEqual([]);
    expect(
      codes(make({ employee_count_range: "10,001+", latest_headcount: 500 })),
    ).toEqual(["size_headcount_mismatch"]);
  });

  it("size_headcount_mismatch for implausible revenue per employee", () => {
    expect(MAX_REVENUE_PER_EMPLOYEE_USD).toBe(500000);
    expect(
      codes(
        make({
          employee_count_range: "1-10",
          latest_headcount: 4,
          revenue_range: "$10M-$50M",
        }),
      ),
    ).toEqual(["size_headcount_mismatch"]);
    expect(
      codes(
        make({
          employee_count_range: "51-200",
          latest_headcount: 120,
          revenue_range: "$10M-$50M",
        }),
      ),
    ).toEqual([]);
  });

  it("skips the size rule when data is missing or oddly formatted", () => {
    expect(codes(make({ latest_headcount: undefined, employee_count_range: "1-2" }))).toEqual([]);
    expect(codes(make({ employee_count_range: "lots", latest_headcount: 5 }))).toEqual([]);
    expect(codes(make({ revenue_range: "<$1M", latest_headcount: 1 }))).toEqual([]);
    expect(codes(make({ revenue_range: "unknown", latest_headcount: 1 }))).toEqual([]);
    expect(codes(make({ latest_headcount: 0, revenue_range: "$10M-$50M" }))).toEqual([]);
  });
});

describe("status", () => {
  it("is rejected when name, domain and LinkedIn are all missing", () => {
    const v = validateCompanies([
      make({ name: "", primary_domain: "", professional_network_url: "" }),
    ])[0];
    expect(v.status).toBe("rejected");
  });

  it("is flagged for a missing name alone", () => {
    expect(validateCompanies([make({ name: "" })])[0].status).toBe("flagged");
  });

  it("is rejected for a later duplicate but not the kept one", () => {
    const a = make({ crustdata_company_id: 1 });
    const b = make({ crustdata_company_id: 2 });
    expect(validateCompanies([a, b]).map((v) => v.status)).toEqual([
      "valid",
      "rejected",
    ]);
  });

  it("gives the expected verdicts on the fixtures, aligned by index", () => {
    const result = validateCompanies(FIXTURE_COMPANIES);
    expect(result).toHaveLength(FIXTURE_COMPANIES.length);
    expect(result.map((v) => v.status)).toEqual([
      "valid", // clean
      "flagged", // LinkedIn only
      "flagged", // wa.link
      "valid", // kept
      "rejected", // later duplicate
      "flagged", // no domain
      "valid", // messy name is not a rule
      "flagged", // headcount outside range
      "flagged", // implausible revenue
      "rejected", // nothing identifying
    ]);
  });

  it("is deterministic and does not mutate input", () => {
    const before = JSON.stringify(FIXTURE_COMPANIES);
    expect(validateCompanies(FIXTURE_COMPANIES)).toEqual(
      validateCompanies(FIXTURE_COMPANIES),
    );
    expect(JSON.stringify(FIXTURE_COMPANIES)).toBe(before);
  });
});

describe("odd inputs", () => {
  it("never throw", () => {
    const odd = [
      make({ latest_headcount: NaN, employee_count_range: "5-1" }),
      make({ latest_headcount: Infinity, revenue_range: "$1e99M" }),
      make({ website: "::::", primary_domain: "http://", name: "\u0000" }),
      make({ employee_count_range: "-", revenue_range: "-$", latest_headcount: -5 }),
      { ...clean, name: undefined, website: null, primary_domain: 5 } as unknown as RawCompany,
    ];
    expect(() => validateCompanies(odd)).not.toThrow();
    expect(validateCompanies(odd)).toHaveLength(odd.length);
    expect(validateCompanies([])).toEqual([]);
  });
});

